using System.Text.Json;
using Yukkuri.Simulation;
int passed=0,failed=0;
void Require(bool condition,string reason){if(!condition)throw new Exception(reason);}
void Check(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Tick(WorldSimulation sim,double worldSeconds){double end=sim.State.WorldSeconds+worldSeconds;while(sim.State.WorldSeconds<end-1e-8){sim.AdvanceInteractionPresentation(.025);sim.Advance(.025);}}
WorldSimulation Yard(int count=5){var s=new WorldState{InteractionPlaytest=true,MilestoneScenario=true,EconomyProgression=true,CourtyardLifeVersion=1,Money=240,Food=50,StationWaterPortions=20,Regions=[new(){Id="home",Name="睡眠检查",Kind=RegionKind.Sanctuary}],AutonomousBreeding=false};for(int n=0;n<count;n++){var c=new Creature{Id="oil-"+n,Name="油"+n,X=(n-2)*1.4,Z=1,TargetX=(n-2)*1.4,TargetZ=1,Fullness=80,Energy=90,Health=100,Trust=80,Patience=.7,Body=new(){Id="body-"+n,SpeciesId="reimu"},Registration=new(){IdentityId="person-"+n},Interaction=new(){Enabled=true,Hydration=80,Sleepiness=60,NextAutonomyAt=1e9,ToyInterest=0,Accessory=new(){Id="accessory-"+n}},Family=new(){NextCareAt=1e9,NextSocialAt=1e9,NextBreedingDecisionAt=1e9},DecisionIn=1e9};GrowthRules.Initialize(c,false);s.Creatures.Add(c);}s.SelectedId=s.Creatures[0].Id;var sim=new WorldSimulation(s);sim.Config.WildGrassEnabled=false;sim.State.ShelterStock=1;Require(sim.PlaceShelter(0,-5).Success,"place hut");return sim;}
void Inside(WorldSimulation sim,double time=350){sim.State.WorldSeconds=time;var h=sim.State.Shelters[0];int n=0;foreach(var c in sim.State.Creatures){c.X=c.TargetX=h.X+(n%2==0?-.5:.5);c.Z=c.TargetZ=h.Z+(n/2-1)*.5;h.Residents.Add(new(){CreatureId=c.Id,Slot=n++,Phase=ShelterVisitPhase.Inside,VisualHidden=true});}}
foreach(int speed in WorldSimulation.CourtyardSpeeds)Check("simultaneous entry and collision restoration "+speed+"x",()=>{var sim=Yard();sim.SetCourtyardSpeed(speed);sim.State.WorldSeconds=350;var h=sim.State.Shelters[0];var starts=sim.State.Creatures.Select(c=>(c.X,c.Z)).ToArray();Tick(sim,.25);Require(h.Residents.Count==5,"entry reservations serialized");Require(sim.State.Creatures.All(c=>sim.IsShelterCollisionSuppressed(c)),"approaching collider active");Require(sim.State.Creatures.Select((c,n)=>WorldSimulation.Distance(c.X,c.Z,starts[n].X,starts[n].Z)>.001).All(x=>x),"arrival waited for another entrant");Tick(sim,30);Require(sim.State.Creatures.All(c=>sim.IsShelteredHidden(c)),"five failed entry "+string.Join(" / ",sim.State.Creatures.Select(c=>c.Activity)));sim.State.WorldSeconds=550;foreach(var c in sim.State.Creatures)sim.RequestShelterResidentExit(c.Id);Tick(sim,1);Require(h.Residents.All(v=>v.Phase==ShelterVisitPhase.Exiting),"exit queue");Tick(sim,20);Require(h.Residents.Count==0&&sim.State.Creatures.All(c=>!sim.IsShelterCollisionSuppressed(c)),"collision did not return");Tick(sim,3);foreach(var a in sim.State.Creatures)foreach(var b in sim.State.Creatures.Where(b=>b!=a))Require(WorldSimulation.Distance(a.X,a.Z,b.X,b.Z)>=WorldSimulation.InteractionFootprint(a)+WorldSimulation.InteractionFootprint(b)-.0001,"exit overlap unresolved");SaveStore.Validate(sim.State);});
foreach(int season in Enumerable.Range(0,4))Check("night sleep through seasonal sunrise "+season,()=>{var sim=Yard();var date=CourtyardCalendar.At(season*4200);double dusk=season*4200+(date.Sunset-8)*25;double dawn=dusk+(24-date.Sunset+date.Sunrise)*25;Inside(sim,dusk);foreach(var c in sim.State.Creatures){c.Interaction.Sleepiness=30;c.Interaction.Physiology.Bladder=c.Interaction.Physiology.Bowel=0;}Tick(sim,1);while(sim.State.WorldSeconds<dawn-.25){Tick(sim,.25);Require(sim.State.Creatures.All(c=>c.Interaction.Resting&&sim.IsShelteredHidden(c)),"woke before dawn at "+sim.State.WorldSeconds);}Tick(sim,30);Require(sim.State.Shelters[0].Residents.Count==0,"did not wake at sunrise");});
Check("ordinary daytime tiredness waits for evening",()=>{var sim=Yard(1);sim.Selected!.Interaction.Sleepiness=75;Tick(sim,40);Require(!sim.Selected.Interaction.Resting&&sim.State.Shelters[0].Residents.Count==0,"ordinary day sleep");});
Check("extreme daytime tiredness takes a finite nap",()=>{var sim=Yard(1);sim.Selected!.Interaction.Sleepiness=95;Tick(sim,30);Require(sim.Selected.Interaction.Resting&&sim.IsShelteredHidden(sim.Selected),"no exceptional nap");Tick(sim,110);Require(!sim.Selected.Interaction.Resting&&!sim.IsShelteredHidden(sim.Selected),"nap never ends");});
foreach(var need in new[]{"food","water","bladder","bowel"})Check("urgent "+need+" wakes and exits at night",()=>{var sim=Yard(1);Inside(sim);var c=sim.Selected!;if(need=="food")c.Fullness=19;if(need=="water")c.Interaction.Hydration=19;if(need=="bladder")c.Interaction.Physiology.Bladder=99;if(need=="bowel")c.Interaction.Physiology.Bowel=99;bool outside=false,relieved=false;for(int n=0;n<80;n++){Tick(sim,.25);outside|=!sim.IsShelterCollisionSuppressed(c)&&sim.State.Shelters[0].Residents.Count==0;relieved|=need=="bladder"?c.Interaction.Physiology.Urinations>0:need=="bowel"?c.Interaction.Physiology.Defecations>0:true;}Require(outside&&relieved,"urgent need never exited/relieved "+c.Activity);Require(sim.State.RoomObjects.Where(o=>WorldSimulation.IsWaste(o.Kind)).All(o=>!ShelterGeometry.OverlapsInterior(o.X,o.Z+5,0,ShelterGeometry.SharedScale)),"waste indoors");});
Check("moderate needs do not wake a night sleeper",()=>{var sim=Yard(1);Inside(sim);var c=sim.Selected!;c.Fullness=c.Interaction.Hydration=35;c.Interaction.Physiology.Bladder=c.Interaction.Physiology.Bowel=86;Tick(sim,5);Require(c.Interaction.Resting&&sim.IsShelteredHidden(c)&&!c.Interaction.Physiology.Active,"ordinary need woke sleeper");});
Check("no hut still sleeps at night and wakes at dawn",()=>{var sim=Yard(1);sim.State.Shelters.Clear();sim.State.WorldSeconds=540;sim.Selected!.Interaction.Sleepiness=10;Tick(sim,2);Require(sim.Selected.Interaction.Resting,"no outdoor night sleep");Tick(sim,10);Require(!sim.Selected.Interaction.Resting,"outdoor dawn sleep continues");});
Check("collision exemption is derived after load and clears on interrupted entry",()=>{var sim=Yard(1);sim.State.WorldSeconds=350;Tick(sim,.25);var loaded=new WorldSimulation(JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(sim.State,SaveStore.JsonOptions),SaveStore.JsonOptions)!);var c=loaded.Selected!;Require(loaded.IsShelterCollisionSuppressed(c),"lost entry state");c.Interaction.Carried=true;Require(!loaded.IsShelterCollisionSuppressed(c),"carried body retains exemption");c.Interaction.Carried=false;loaded.State.Shelters[0].Residents.Clear();Require(!loaded.IsShelterCollisionSuppressed(c),"cancelled entry retains exemption");});
Check("legacy single hut can be found for sleep and released at sunrise",()=>{var sim=Yard(1);var h=sim.State.Shelters[0];h.Capacity=1;h.DoorOpen=true;var c=sim.Selected!;c.X=c.TargetX=0;c.Z=c.TargetZ=-2;sim.State.WorldSeconds=350;Tick(sim,30);Require(h.GuestId==c.Id&&c.Interaction.Resting&&sim.IsShelterCollisionSuppressed(c),"legacy sleep entry failed "+c.Activity);sim.State.WorldSeconds=550;Tick(sim,25);Require(h.GuestId==null&&!sim.IsShelterCollisionSuppressed(c),"legacy sunrise did not release collision");});
Check("sixth resident does not exceed hut capacity",()=>{var sim=Yard(6);sim.State.WorldSeconds=350;Tick(sim,35);Require(sim.State.Shelters[0].Residents.Count==5&&sim.State.Creatures.Count(sim.IsShelteredHidden)==5,"capacity changed");});
Check("paused and close-up clocks preserve schedule",()=>{foreach(bool close in new[]{false,true}){var sim=Yard(1);Inside(sim);sim.State.Mode=close?PlayMode.CloseUp:PlayMode.Management;sim.State.Settings.Pause=!close;double sleep=sim.Selected!.Interaction.Sleepiness;for(int n=0;n<40;n++){sim.AdvanceInteractionPresentation(.025);sim.Advance(.025);}Require(sim.State.WorldSeconds==350&&sim.Selected.Interaction.Sleepiness==sleep,"schedule advanced while frozen");}});
Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
